// In-browser stand-in for the FastAPI backend, used by the preview build.
// Runs advance on a timer through the same ten stages, pause for manual annotation, and serve
// results generated by backend/app/demo.py (exported to src/mock/demo.json).

import demoData from "../mock/demo.json";
import type { Api } from "./api";
import { ApiError } from "./api";
import type {
  Catalog, DEResult, PipelineConfig, QCResults, Run, RunCreate, RunSummary, Sample, StageId, StageStatus,
  UmapResult,
} from "./types";

interface DemoFile {
  stages: Catalog["stages"];
  standard_preset: PipelineConfig;
  samples: Sample[];
  logs: Record<string, string[]>;
  results: {
    read_qc: NonNullable<QCResults["read_qc"]>;
    alignment: NonNullable<QCResults["alignment"]>;
    cell_qc: NonNullable<QCResults["cell_qc"]>;
    umap: Omit<UmapResult, "labels">;
    markers: { genes: string[]; dots: { cluster: string; gene: string; avg: number; pct: number }[]; table: never[] };
    de: {
      genes: string[];
      by_cell_type: Record<string, { log2fc: number[]; padj: number[]; base_mean: number[] }>;
    };
  };
}

const D = demoData as unknown as DemoFile;
const STAGE_IDS = D.stages.map((s) => s.id);

interface Sim {
  run: Run;
  secondsPerStage: number;
  lastTick: number;
  failAt?: { stage: StageId; message: string };
  labels: Record<string, string>;
  logs: Partial<Record<StageId, string[]>>;
}

const sims = new Map<string, Sim>();

const clone = <T,>(x: T): T => JSON.parse(JSON.stringify(x));
const iso = (msAgo: number) => new Date(Date.now() - msAgo).toISOString();
const H = 3600_000;

function stagesFor(config: PipelineConfig): StageStatus[] {
  return STAGE_IDS.map((id) => ({
    id, state: config[id].enabled ? "pending" : "skipped",
    started_at: null, finished_at: null, progress: 0, message: "",
  }));
}

function suggestedLabels(): Record<string, string> {
  return Object.fromEntries(D.results.umap.clusters.map((c) => [c.id, c.suggested_label ?? `Cluster ${c.id}`]));
}

function seed() {
  if (sims.size) return;
  const preset = clone(D.standard_preset);

  // 1 · Finished run with every result available.
  const done: Run = {
    id: "run_pbmc_ifnb", name: "PBMC · IFN-β stimulation",
    description: "Three donors, control vs IFN-β (6 h), 10x 3′ v3.",
    organism: "human", reference: "GRCh38-2024-A", input_type: "bcl",
    input_path: "/data/bcl/241011_A01234_0451_BHXYZDSX7", sample_sheet: null,
    samples: clone(D.samples), config: clone(preset),
    state: "done", created_at: iso(120 * H), updated_at: iso(118 * H), demo: true,
    stages: stagesFor(preset).map((s, i) => ({
      ...s, state: "done", progress: 1, message: "Complete",
      started_at: iso(120 * H - i * 0.4 * H), finished_at: iso(120 * H - (i + 1) * 0.4 * H),
    })),
  };
  done.config.de.params.reference = "Control";
  sims.set(done.id, {
    run: done, secondsPerStage: 0, lastTick: Date.now(), labels: suggestedLabels(),
    logs: Object.fromEntries(STAGE_IDS.map((id) => [id, D.logs[id]])),
  });

  // 2 · Running now; pauses at annotation so you can name clusters.
  const running: Run = {
    id: "run_pbmc_stm2457", name: "PBMC · METTL3 inhibitor",
    description: "STM2457 (5 µM, 24 h) vs vehicle, three donors. Does m6A loss shift monocyte programs?",
    organism: "human", reference: "GRCh38-2024-A", input_type: "bcl",
    input_path: "/data/bcl/241018_A01234_0456_BHXYZDSX7", sample_sheet: null,
    samples: [1, 2, 3].flatMap((d) => [
      { id: `Donor${d}_Veh`, condition: "Vehicle", replicate: d },
      { id: `Donor${d}_STM`, condition: "STM2457", replicate: d },
    ]),
    config: clone(preset), state: "running", created_at: iso(0.6 * H), updated_at: iso(0), demo: true,
    stages: stagesFor(preset),
  };
  running.config.de.params.reference = "Vehicle";
  ["demux", "read_qc"].forEach((id, i) => {
    const s = running.stages.find((x) => x.id === id)!;
    Object.assign(s, { state: "done", progress: 1, message: "Complete",
      started_at: iso(0.6 * H - i * 0.2 * H), finished_at: iso(0.4 * H - i * 0.2 * H) });
  });
  Object.assign(running.stages.find((x) => x.id === "align")!, {
    state: "running", progress: 0.35, started_at: iso(0.2 * H), message: D.logs.align[1],
  });
  sims.set(running.id, {
    run: running, secondsPerStage: 9, lastTick: Date.now(), labels: {},
    logs: { demux: D.logs.demux, read_qc: D.logs.read_qc, align: D.logs.align.slice(0, 2) },
  });

  // 3 · Failed, to show how errors read.
  const failed: Run = {
    id: "run_organoid_fto", name: "Lung organoid · FTO knockdown",
    description: "shFTO vs shScramble, two lines, CellBender for ambient removal.",
    organism: "human", reference: "GRCh38-2024-A", input_type: "fastq",
    input_path: "/data/fastq/2410_organoid", sample_sheet: null,
    samples: [
      { id: "LineA_shScr", condition: "shScramble", replicate: 1 }, { id: "LineB_shScr", condition: "shScramble", replicate: 2 },
      { id: "LineA_shFTO", condition: "shFTO", replicate: 1 }, { id: "LineB_shFTO", condition: "shFTO", replicate: 2 },
    ],
    config: clone(preset), state: "failed", created_at: iso(30 * H), updated_at: iso(28 * H), demo: true,
    stages: stagesFor({ ...preset, demux: { ...preset.demux, enabled: false } }),
  };
  failed.config.demux.enabled = false;
  failed.config.ambient = { tool: "cellbender", enabled: true,
    params: { expected_cells: 8000, total_droplets: 40000, fpr: 0.01, use_gpu: true } };
  failed.config.de.params.reference = "shScramble";
  ["read_qc", "align"].forEach((id) => Object.assign(failed.stages.find((x) => x.id === id)!, {
    state: "done", progress: 1, message: "Complete", started_at: iso(30 * H), finished_at: iso(29 * H) }));
  Object.assign(failed.stages.find((x) => x.id === "ambient")!, {
    state: "failed", progress: 0.42, started_at: iso(29 * H), finished_at: iso(28 * H),
    message: "CellBender ran out of GPU memory on LineB_shFTO. Lower “Droplets to include” to 25,000 or turn off GPU, then retry.",
  });
  sims.set(failed.id, {
    run: failed, secondsPerStage: 7, lastTick: Date.now(), labels: {},
    logs: {
      read_qc: D.logs.read_qc, align: D.logs.align,
      ambient: ["cellbender remove-background v0.3.2", "LineA_shScr: 8,104 cells, 39,872 droplets",
        "LineB_shFTO: training epoch 112/150",
        "ERROR torch.OutOfMemoryError: CUDA out of memory. Tried to allocate 2.31 GiB (GPU 0; 15.7 GiB total)"],
    },
  });
}

function tick(sim: Sim) {
  const now = Date.now();
  let dt = (now - sim.lastTick) / 1000;
  sim.lastTick = now;
  const run = sim.run;
  while (dt > 0 && (run.state === "running" || run.state === "queued")) {
    run.state = "running";
    const cur = run.stages.find((s) => s.state === "running" || s.state === "pending");
    if (!cur) { run.state = "done"; break; }
    if (cur.state === "pending") {
      cur.state = "running"; cur.started_at = new Date().toISOString(); cur.progress = 0;
      if (cur.id === "annotate" && run.config.annotate.tool === "seurat_markers" && !Object.keys(sim.labels).length) {
        cur.state = "needs_input"; cur.progress = 1; cur.message = "Name each cluster to continue";
        sim.logs.annotate = D.logs.annotate;
        run.state = "needs_input";
        break;
      }
    }
    const lines = D.logs[cur.id] ?? ["Working"];
    const need = (1 - cur.progress) * sim.secondsPerStage;
    const step = Math.min(dt, need);
    cur.progress = Math.min(1, cur.progress + step / sim.secondsPerStage);
    dt -= step;
    const shown = Math.max(1, Math.ceil(cur.progress * lines.length));
    sim.logs[cur.id] = lines.slice(0, shown);
    cur.message = lines[shown - 1];
    if (sim.failAt?.stage === cur.id && cur.progress > 0.5) {
      cur.state = "failed"; cur.message = sim.failAt.message; run.state = "failed"; break;
    }
    if (cur.progress >= 1) {
      cur.state = "done"; cur.finished_at = new Date().toISOString(); cur.message = "Complete";
      if (cur.id === "annotate" && run.config.annotate.tool === "celltypist") sim.labels = suggestedLabels();
    }
  }
  if (!run.stages.some((s) => s.state === "pending" || s.state === "running" || s.state === "needs_input" || s.state === "failed")
      && run.state === "running") run.state = "done";
  if (sim.secondsPerStage && run.stages.some((s) => s.state === "running")) run.updated_at = new Date().toISOString();
}

function get(id: string): Sim {
  seed();
  const sim = sims.get(id);
  if (!sim) throw new ApiError(404, `No run with ID ${id}.`);
  tick(sim);
  return sim;
}

const done = (run: Run, id: StageId) => {
  const s = run.stages.find((x) => x.id === id);
  return s?.state === "done" || s?.state === "needs_input" || s?.state === "skipped";
};
const needStage = (run: Run, id: StageId, what: string) => {
  if (!done(run, id)) throw new ApiError(409, `${what} appear after the ${D.stages.find((s) => s.id === id)!.name.toLowerCase()} stage finishes.`);
};

function summary(sim: Sim): RunSummary {
  const run = sim.run;
  const active = run.stages.filter((s) => s.state !== "skipped");
  const progress = active.reduce((a, s) => a + (s.state === "done" ? 1 : s.state === "running" ? s.progress : 0), 0) / active.length;
  const current = run.stages.find((s) => ["running", "needs_input", "failed"].includes(s.state))?.id ?? null;
  return {
    id: run.id, name: run.name, description: run.description, state: run.state,
    created_at: run.created_at, updated_at: run.updated_at, n_samples: run.samples.length,
    conditions: [...new Set(run.samples.map((s) => s.condition))], progress, current_stage: current,
    cells: done(run, "doublets") ? scaledFunnel(run).at(-1)!.cells : null, demo: true,
    stages: run.stages.map((s) => ({ id: s.id, state: s.state })),
  };
}

function scaledFunnel(run: Run) {
  const f = D.results.cell_qc.funnel;
  const k = run.samples.length / D.samples.length;
  return f.map((s) => ({ ...s, cells: Math.round(s.cells * k) }));
}

function rand(seedStr: string) {
  let h = 2166136261;
  for (const ch of seedStr) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
  return () => {
    h = Math.imul(h ^ (h >>> 15), 2246822507) >>> 0;
    h = Math.imul(h ^ (h >>> 13), 3266489909) >>> 0;
    return ((h ^= h >>> 16) >>> 0) / 4294967296;
  };
}

const wait = <T,>(x: T, ms = 140) => new Promise<T>((r) => setTimeout(() => r(x), ms));

export const mockApi: Api = {
  mode: "mock",
  async health() { return { ok: true, demo_mode: true }; },
  async catalog() {
    return wait({ stages: clone(D.stages), standard_preset: clone(D.standard_preset) }, 60);
  },
  async listRuns() {
    seed();
    return wait([...sims.values()].map((s) => { tick(s); return summary(s); })
      .sort((a, b) => b.created_at.localeCompare(a.created_at)));
  },
  async getRun(id) { return wait(clone(get(id).run), 60); },
  async createRun(body: RunCreate) {
    seed();
    const conditions = [...new Set(body.samples.map((s) => s.condition))];
    if (conditions.length < 2) throw new ApiError(422, "Differential expression needs at least two conditions.");
    for (const c of conditions) {
      if (body.samples.filter((s) => s.condition === c).length < 2)
        throw new ApiError(422, `“${c}” has one sample. Pseudobulk DE needs at least two replicates per condition.`);
    }
    if (!conditions.includes(String(body.config.de.params.reference)))
      throw new ApiError(422, `Reference condition “${body.config.de.params.reference}” doesn't match any sample's condition.`);
    const id = "run_" + Math.random().toString(16).slice(2, 10);
    const run: Run = { ...clone(body), id, state: "queued", created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(), stages: stagesFor(body.config), demo: true };
    sims.set(id, { run, secondsPerStage: 5, lastTick: Date.now(), labels: {}, logs: {} });
    return wait(clone(run), 300);
  },
  async cancelRun(id) {
    const sim = get(id);
    if (sim.run.state === "running") {
      sim.run.state = "cancelled";
      const cur = sim.run.stages.find((s) => s.state === "running");
      if (cur) { cur.state = "failed"; cur.message = "Cancelled"; }
    }
    return wait(clone(sim.run));
  },
  async retryRun(id) {
    const sim = get(id);
    const failed = sim.run.stages.find((s) => s.state === "failed");
    if (failed) {
      Object.assign(failed, { state: "pending", progress: 0, message: "" });
      if (sim.run.id === "run_organoid_fto") sim.run.config.ambient.params.total_droplets = 25000;
    }
    sim.run.state = "running";
    sim.lastTick = Date.now();
    return wait(clone(sim.run));
  },
  async logs(id, stage) { return wait([...(get(id).logs[stage] ?? [])], 60); },
  async saveAnnotations(id, labels) {
    const sim = get(id);
    const clean = Object.fromEntries(Object.entries(labels).map(([k, v]) => [k, v.trim()]).filter(([, v]) => v));
    if (!Object.keys(clean).length) throw new ApiError(422, "Give at least one cluster a label.");
    sim.labels = clean;
    const ann = sim.run.stages.find((s) => s.id === "annotate")!;
    if (sim.run.state === "needs_input") {
      Object.assign(ann, { state: "running", progress: 0.2, message: "Applying labels" });
      sim.run.state = "running";
      sim.lastTick = Date.now();
    }
    return wait(clone(sim.run), 250);
  },
  async qc(id) {
    const { run } = get(id);
    const map = <T extends { sample: string }>(rows: T[]) =>
      run.samples.map((s, i) => ({ ...rows[i % rows.length], sample: s.id }));
    const out: QCResults = {};
    if (done(run, "read_qc")) out.read_qc = map(D.results.read_qc);
    if (done(run, "align")) out.alignment = map(D.results.alignment);
    if (done(run, "doublets")) {
      out.cell_qc = { ...D.results.cell_qc, samples: map(D.results.cell_qc.samples), funnel: scaledFunnel(run),
        thresholds: {
          min_features: Number(run.config.cell_qc.params.min_features),
          max_features: Number(run.config.cell_qc.params.max_features),
          max_percent_mt: Number(run.config.cell_qc.params.max_percent_mt),
        } };
    }
    return wait(out);
  },
  async umap(id) {
    const sim = get(id);
    needStage(sim.run, "cluster", "Clusters");
    const u = D.results.umap;
    const n = sim.run.samples.length;
    return wait({ ...u, samples: sim.run.samples, sample: n === 6 ? u.sample : u.sample.map((s) => s % n),
      labels: { ...sim.labels } }, 200);
  },
  async markers(id) {
    const sim = get(id);
    needStage(sim.run, "cluster", "Markers");
    return wait({ ...D.results.markers, table: [] });
  },
  async deSummary(id) {
    const sim = get(id);
    needStage(sim.run, "de", "Differential expression results");
    const p = sim.run.config.de.params as { padj: number; lfc: number };
    const types = [...new Set(Object.values(sim.labels))];
    return wait({
      cutoffs: { padj: p.padj, lfc: p.lfc },
      cell_types: types.map((ct) => {
        const d = deFor(sim, ct);
        let up = 0, down = 0;
        d.log2fc.forEach((l, i) => {
          if (d.padj[i] < p.padj) { if (l >= p.lfc) up++; else if (l <= -p.lfc) down++; }
        });
        return { cell_type: ct, up, down, tested: d.log2fc.length };
      }),
    });
  },
  async de(id, cellType) {
    const sim = get(id);
    needStage(sim.run, "de", "Differential expression results");
    if (!Object.values(sim.labels).includes(cellType)) throw new ApiError(404, `No cell type named ${cellType}.`);
    const d = deFor(sim, cellType);
    const genes = D.results.de.genes.map((gene, i) => ({
      gene, log2fc: d.log2fc[i], padj: d.padj[i], base_mean: d.base_mean[i],
    })).sort((a, b) => a.padj - b.padj);
    const ref = String(sim.run.config.de.params.reference);
    const test = [...new Set(sim.run.samples.map((s) => s.condition))].find((c) => c !== ref) ?? "";
    const r = rand(sim.run.id + cellType);
    const rows = genes.slice(0, 24).map((g) => {
      const v = sim.run.samples.map((s) => (s.condition === ref ? -0.85 : 0.85) * Math.sign(g.log2fc) + (r() - 0.5) * 0.7);
      const mean = v.reduce((a, b) => a + b, 0) / v.length;
      const sd = Math.sqrt(v.reduce((a, b) => a + (b - mean) ** 2, 0) / v.length) || 1;
      return { gene: g.gene, values: v.map((x) => +((x - mean) / sd).toFixed(2)) };
    });
    const result: DEResult = {
      cell_type: cellType, contrast: { factor: "condition", test, reference: ref }, genes,
      heatmap: { samples: sim.run.samples.map((s) => s.id), rows },
    };
    return wait(result, 180);
  },
};

function deFor(sim: Sim, cellType: string) {
  const cluster = Object.entries(sim.labels).find(([, v]) => v === cellType)?.[0] ?? "0";
  const original = D.results.umap.clusters.find((c) => c.id === cluster)?.suggested_label ?? "CD4 T naive";
  return D.results.de.by_cell_type[original] ?? Object.values(D.results.de.by_cell_type)[0];
}
